"""Sliding Window Maximum — monotonic deque of indices.

The deque keeps indices whose values are strictly decreasing, so its head is
always the maximum of the current window. Every index enters and leaves once.

Time: O(n)   Space: O(k)
"""
from collections import deque
from typing import List


class Solution:
    def maxSlidingWindow(self, nums: List[int], k: int) -> List[int]:
        dq, out = deque(), []
        for i, value in enumerate(nums):
            while dq and nums[dq[-1]] <= value:
                dq.pop()               # smaller values can never win again
            dq.append(i)
            if dq[0] == i - k:
                dq.popleft()           # head slid out of the window
            if i >= k - 1:
                out.append(nums[dq[0]])
        return out
